s8-introduction-to-bit-manipulation-theo.code:
// Approach: Use masks for individual bits: AND tests, OR sets, XOR toggles, and AND with an inverted
//   mask clears. Positions are zero-based.
#include <cstdint>
#include <stdexcept>
using namespace std;
bool testBit(uint32_t value, int bit) {
    if (bit < 0 || bit >= 32) throw out_of_range("bit");
    return (value & (uint32_t(1) << bit)) != 0;
}
uint32_t setBit(uint32_t value, int bit) {
    if (bit < 0 || bit >= 32) throw out_of_range("bit");
    return value | (uint32_t(1) << bit);
}
uint32_t clearBit(uint32_t value, int bit) {
    if (bit < 0 || bit >= 32) throw out_of_range("bit");
    return value & ~(uint32_t(1) << bit);
}
uint32_t toggleBit(uint32_t value, int bit) {
    if (bit < 0 || bit >= 32) throw out_of_range("bit");
    return value ^ (uint32_t(1) << bit);
}

s8-check-if-the-i-th-bit-is-set-or-not.code:
// Approach: Shift a one to zero-based position i and AND it with the number. Use an unsigned type to
//   avoid signed-shift pitfalls.
#include <cstdint>
#include <stdexcept>
using namespace std;
bool isBitSet(uint32_t value, int i) {
    if (i < 0 || i >= 32) throw out_of_range("bit index");
    return (value & (uint32_t(1) << i)) != 0;
}

s8-check-if-a-number-is-odd-or-not.code:
// Approach: The least significant bit is 1 exactly when an integer is odd.
bool isOdd(int n) {
    return (n & 1) != 0;
}

s8-check-if-a-number-is-power-of-2-or-no.code:
// Approach: A positive power of two has exactly one set bit, which n & (n-1) clears.
bool isPowerOfTwo(int n) {
    return n > 0 && (n & (n - 1)) == 0;
}

s8-count-the-number-of-set-bits.code:
// Approach: Repeatedly clear the rightmost set bit with n &= n-1. The loop runs once per set bit.
#include <cstdint>
using namespace std;
int countSetBits(uint32_t n) {
    int count = 0;
    while (n) {
        n &= n - 1;
        ++count;
    }
    return count;
}

s8-set-unset-the-rightmost-unset-bit.code:
// Approach: n | (n+1) sets the lowest zero bit; n & (n-1) clears the lowest one bit. Unsigned
//   arithmetic makes overflow behavior defined.
#include <cstdint>
using namespace std;
uint32_t setRightmostZero(uint32_t n) {
    return n | (n + 1); // if all bits are already 1, n stays unchanged
}
uint32_t clearRightmostOne(uint32_t n) {
    return n & (n - 1); // if n is 0, it stays 0
}

s8-swap-two-numbers.code:
// Approach: XOR swapping is a bitwise exercise: three XORs exchange values, but the alias check is
//   essential. Prefer std::swap in production code.
void xorSwap(int& a, int& b) {
    if (&a == &b) return;
    a ^= b;
    b ^= a;
    a ^= b;
}

s8-divide-two-integers-without-using-mul.code:
// Approach: Subtract the largest shifted divisor that fits, from high bit to low bit. Compute
//   magnitudes in 64-bit to handle INT_MIN safely.
#include <climits>
#include <stdexcept>
int divideIntegers(int dividend, int divisor) {
    if (divisor == 0) throw std::invalid_argument("division by zero");
    if (dividend == INT_MIN && divisor == -1) return INT_MAX;
    long long a = dividend, b = divisor;
    unsigned long long left = a < 0 ? -a : a;
    unsigned long long unit = b < 0 ? -b : b;
    unsigned long long quotient = 0;
    for (int bit = 31; bit >= 0; --bit) {
        unsigned long long chunk = unit << bit;
        if (chunk <= left) {
            left -= chunk;
            quotient |= 1ULL << bit;
        }
    }
    long long signedResult = ((dividend < 0) != (divisor < 0))
        ? -(long long)quotient : (long long)quotient;
    return (int)signedResult;
}

s8-count-number-of-bits-to-be-flipped-to.code:
// Approach: XOR marks positions where A and B differ. Count the set bits of that XOR.
#include <cstdint>
using namespace std;
int bitFlips(uint32_t a, uint32_t b) {
    uint32_t different = a ^ b;
    int count = 0;
    while (different) {
        different &= different - 1;
        ++count;
    }
    return count;
}

s8-find-the-number-that-appears-odd-numb.code:
// Approach: XOR cancels every value occurring an even number of times, leaving the one odd-frequency
//   value.
#include <vector>
using namespace std;
int oddOccurrence(const vector<int>& values) {
    int answer = 0;
    for (int value : values) answer ^= value;
    return answer; // assumes exactly one value occurs an odd number of times
}

s8-power-set.code:
// Approach: Each bitmask from 0 to 2^n-1 describes one subset: bit i says whether to include element
//   i.
#include <cstdint>
#include <stdexcept>
#include <vector>
using namespace std;
vector<vector<int>> powerSet(const vector<int>& a) {
    int n = (int)a.size();
    if (n >= 63) throw length_error("too many elements for a 64-bit mask");
    vector<vector<int>> answer;
    for (uint64_t mask = 0; mask < (uint64_t(1) << n); ++mask) {
        vector<int> subset;
        for (int i = 0; i < n; ++i)
            if (mask & (uint64_t(1) << i)) subset.push_back(a[i]);
        answer.push_back(subset);
    }
    return answer;
}

s8-find-xor-of-numbers-from-l-to-r.code:
// Approach: XOR from 0 through n follows a four-value cycle depending on n mod 4. XOR of L..R is
//   prefix(R) XOR prefix(L-1).
#include <cstdint>
using namespace std;
uint64_t xorPrefix(uint64_t n) {
    switch (n & 3ULL) {
        case 0: return n;
        case 1: return 1;
        case 2: return n + 1;
        default: return 0;
    }
}
uint64_t xorRange(uint64_t left, uint64_t right) {
    if (left > right) return 0;
    return xorPrefix(right) ^ (left == 0 ? 0 : xorPrefix(left - 1));
}

s8-find-the-two-numbers-appearing-odd-nu.code:
// Approach: XOR all values to get a^b. Isolate one bit where a and b differ and XOR the two resulting
//   groups separately.
#include <algorithm>
#include <cstdint>
#include <utility>
#include <vector>
using namespace std;
pair<int, int> twoOddOccurrences(const vector<int>& values) {
    uint32_t both = 0;
    for (int value : values) both ^= (uint32_t)value;
    uint32_t separatingBit = both & (~both + 1u);
    uint32_t first = 0, second = 0;
    for (int value : values) {
        if ((uint32_t)value & separatingBit) first ^= (uint32_t)value;
        else second ^= (uint32_t)value;
    }
    int a = (int)first, b = (int)second;
    if (a > b) swap(a, b);
    return {a, b}; // assumes exactly two odd-frequency values
}

s8-print-prime-factors-of-a-number.code:
// Approach: Try divisors only up to the remaining number's square root. Record each prime divisor
//   once, divide out all copies, then append any remaining prime.
#include <vector>
using namespace std;
vector<int> distinctPrimeFactors(int n) {
    vector<int> factors;
    if (n <= 1) return factors;
    for (int p = 2; p <= n / p; ++p) {
        if (n % p != 0) continue;
        factors.push_back(p);
        while (n % p == 0) n /= p;
    }
    if (n > 1) factors.push_back(n);
    return factors;
}

s8-all-divisors-of-a-number.code:
// Approach: Each divisor d up to sqrt(n) pairs with n/d. Avoid duplicating the square root, then sort
//   the answer.
#include <algorithm>
#include <vector>
using namespace std;
vector<int> allDivisors(int n) {
    vector<int> answer;
    if (n <= 0) return answer;
    for (int d = 1; d <= n / d; ++d) {
        if (n % d != 0) continue;
        answer.push_back(d);
        if (d != n / d) answer.push_back(n / d);
    }
    sort(answer.begin(), answer.end());
    return answer;
}

s8-sieve-of-eratosthenes.code:
// Approach: Start with all numbers at least 2 marked prime. For each prime p up to sqrt(n), mark its
//   multiples starting at p².
#include <vector>
using namespace std;
vector<int> primesUpTo(int n) {
    if (n < 2) return {};
    vector<char> prime(n + 1, true);
    prime[0] = prime[1] = false;
    for (int p = 2; p <= n / p; ++p) {
        if (!prime[p]) continue;
        for (long long multiple = 1LL * p * p; multiple <= n; multiple += p)
            prime[multiple] = false;
    }
    vector<int> answer;
    for (int value = 2; value <= n; ++value)
        if (prime[value]) answer.push_back(value);
    return answer;
}

s8-find-prime-factorisation-of-a-number-.code:
// Approach: Precompute the smallest prime factor (SPF) of every value up to n. Repeatedly divide by
//   SPF[n] to list prime factors with multiplicity.
#include <vector>
using namespace std;
vector<int> primeFactorsWithSieve(int n) {
    if (n <= 1) return {};
    vector<int> spf(n + 1);
    for (int i = 2; i <= n; ++i) spf[i] = i;
    for (int p = 2; p <= n / p; ++p) {
        if (spf[p] != p) continue;
        for (long long multiple = 1LL * p * p; multiple <= n; multiple += p)
            if (spf[multiple] == multiple) spf[multiple] = p;
    }
    vector<int> factors;
    while (n > 1) {
        factors.push_back(spf[n]);
        n /= spf[n];
    }
    return factors;
}

s8-power-n-x.code:
// Approach: Use binary exponentiation: multiply the answer for each set bit of the nonnegative
//   exponent, squaring the base after every bit.
long long integerPower(long long base, unsigned int exponent) {
    long long answer = 1;
    while (exponent > 0) {
        if (exponent & 1u) answer *= base;
        exponent >>= 1;
        if (exponent) base *= base;
    }
    return answer; // assumes the mathematical result fits in long long
}
